CREATE TABLE "wp_posts" (
    "ID" INT8 NOT NULL,
    "post_author" INT8 NOT NULL,
    "post_date" TIMESTAMP NOT NULL,
    "post_date_gmt" TIMESTAMP NOT NULL,
    "post_content" STRING NOT NULL,
    "post_title" STRING NOT NULL,
    "post_excerpt" STRING,
    "post_status" STRING(20) NOT NULL,
    "comment_status" STRING(20) NOT NULL,
    "ping_status" STRING(20) NOT NULL,
    "post_password" STRING(255),
    "post_name" STRING(200) NOT NULL,
    "to_ping" STRING,
    "pinged" STRING,
    "post_modified" TIMESTAMP NOT NULL,
    "post_modified_gmt" TIMESTAMP NOT NULL,
    "post_content_filtered" STRING,
    "post_parent" INT8 NOT NULL,
    "guid" STRING(255) NOT NULL,
    "menu_order" INT4 NOT NULL,
    "post_type" STRING(20) NOT NULL,
    "post_mime_type" STRING(100),
    "comment_count" INT8 NOT NULL,
    PRIMARY KEY ("ID")
);








